import type { Bundle } from "../types.js";
import { reproducibleEnv } from "../capture/env.js";

/**
 * Generate a Dockerfile that recreates the bundle's environment.
 *
 * This is a *starting point*, not a guarantee: we do not run `docker` while
 * capturing (it is often absent, as it is on CI runners), so the image is
 * derived from the recorded fingerprint rather than from a verified build. The
 * generated file says so in a comment instead of pretending otherwise.
 */

export interface DockerfileOptions {
  /** Base image override; defaults to one derived from the recorded Node version. */
  readonly baseImage?: string;
}

export function generateDockerfile(bundle: Bundle, options: DockerfileOptions = {}): string {
  const node = bundle.environment.node.replace(/^v/, "");
  const base = options.baseImage ?? defaultBaseImage(bundle, node);
  const lines: string[] = [];

  lines.push("# Generated by repropack " + bundle.producer.version + " for bundle " + bundle.id.slice(0, 12) + ".");
  lines.push("#");
  lines.push("# This image reproduces the *environment* recorded in the bundle. It is");
  lines.push("# derived from the manifest, not from a verified build: repropack does not");
  lines.push("# require docker at capture time.");
  lines.push("#");
  lines.push("#   docker build -t repropack-" + bundle.id.slice(0, 8) + " .");
  lines.push("#   docker run --rm repropack-" + bundle.id.slice(0, 8));
  lines.push("");
  lines.push("FROM " + base);
  lines.push("");

  if (bundle.environment.packageManager) {
    const pm = bundle.environment.packageManager;
    lines.push("# Package manager recorded: " + pm.name + " " + pm.version);
    if (pm.lockfile) lines.push("# Lockfile: " + pm.lockfile);
    if (pm.name === "pnpm" && node) {
      lines.push("RUN corepack enable && corepack prepare pnpm@" + pm.version + " --activate");
    } else if (pm.name === "yarn" && node) {
      lines.push("RUN corepack enable && corepack prepare yarn@" + pm.version + " --activate");
    }
    lines.push("");
  }

  lines.push("WORKDIR /app");
  lines.push("COPY files/ /app/");
  lines.push("");

  // Machine-specific variables (PATH, HOME, TEMP, ...) are deliberately not
  // emitted: the image supplies its own, and copying the capture host's PATH
  // into a Linux container guarantees "command not found".
  const env = reproducibleEnv(bundle.environment.env);
  for (const [name, value] of Object.entries(env).sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    lines.push("ENV " + name + "=" + JSON.stringify(value));
  }
  if (Object.keys(env).length > 0) lines.push("");

  lines.push("ENV TZ=" + JSON.stringify(bundle.environment.timezone));
  lines.push("ENV LANG=" + JSON.stringify(bundle.environment.locale));
  lines.push("");

  if (bundle.command.argv.length > 0) {
    lines.push("# The recorded command, run as-is:");
    lines.push("#   " + bundle.command.argv.map(shellQuote).join(" "));
    lines.push("CMD " + JSON.stringify(bundle.command.argv));
  }

  return lines.join("\n") + "\n";
}

/**
 * Replay entry point for POSIX shells.
 *
 * The command is echoed before running so a reader can see exactly what the
 * container will execute, which matters when the bundle came from somewhere
 * else.
 */
export function generateReplayScript(bundle: Bundle): string {
  const lines: string[] = [];
  lines.push("#!/bin/sh");
  lines.push("# Generated by repropack " + bundle.producer.version + " for bundle " + bundle.id.slice(0, 12) + ".");
  lines.push("# Re-run the recorded command from this directory.");
  lines.push("set -u");
  // A bundle mirrors the project tree under files/, which is what the generated
  // Dockerfile copies into /app. Running from the bundle root would look for
  // src/main.js where only files/src/main.js exists.
  lines.push('cd "$(dirname "$0")/files" || exit 2');
  lines.push("");
  for (const [name, value] of Object.entries(reproducibleEnv(bundle.environment.env)).sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    lines.push("export " + name + "=" + shellQuote(value));
  }
  lines.push("");
  lines.push('echo "repropack: " ' + '"' + escapeForDoubleQuotes(bundle.command.argv.map(shellQuote).join(" ")) + '"');
  lines.push(bundle.command.argv.map(shellQuote).join(" "));
  lines.push("status=$?");
  lines.push('echo "repropack: command exited $status (recorded: ' + String(bundle.command.exitCode) + ')"');
  lines.push("exit $status");
  return lines.join("\n") + "\n";
}

/** Windows counterpart; batch is the one format that needs no interpreter. */
export function generateReplayCmd(bundle: Bundle): string {
  const lines: string[] = [];
  lines.push("@echo off");
  lines.push("rem Generated by repropack " + bundle.producer.version + " for bundle " + bundle.id.slice(0, 12) + ".");
  // Same reason as the posix script: the sources live in files/, not here.
  lines.push('cd /d "%~dp0files"');
  lines.push("");
  for (const [name, value] of Object.entries(reproducibleEnv(bundle.environment.env)).sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    lines.push("set " + name + "=" + value);
  }
  lines.push("");
  lines.push("echo repropack: " + bundle.command.argv.map(shellQuote).join(" "));
  lines.push(bundle.command.argv.map(cmdQuote).join(" "));
  lines.push("echo repropack: command exited %ERRORLEVEL% (recorded: " + String(bundle.command.exitCode) + ")");
  lines.push("exit /b %ERRORLEVEL%");
  return lines.join("\r\n") + "\r\n";
}

function defaultBaseImage(bundle: Bundle, nodeVersion: string): string {
  // The base image is about the *runtime*, so pick by Node version. The OS part
  // only picks the flavour, because a Debian image can run a capture taken on
  // macOS far more often than a macOS-only base can.
  void bundle.environment.platform;
  const major = nodeVersion.split(".")[0] ?? "20";
  return "node:" + major + "-bookworm-slim";
}

function shellQuote(value: string): string {
  if (value.length === 0) return "''";
  if (/^[A-Za-z0-9_./:=@%+-]+$/.test(value)) return value;
  return "'" + value.split("'").join("'\\''") + "'";
}

function cmdQuote(value: string): string {
  if (value.length === 0) return '""';
  if (/^[A-Za-z0-9_./:=@%+-]+$/.test(value)) return value;
  return '"' + value.split('"').join('""') + '"';
}

function escapeForDoubleQuotes(value: string): string {
  return value.split("\\").join("\\\\").split('"').join('\\"');
}